/** Handwritten brand fonts embedded as data URIs (2026-07-19).
 *  @remotion/fonts loadFont silently failed to apply these families at render
 *  (document.fonts stayed empty) while the same code path works for the older
 *  TTFs - embedding sidesteps the loader entirely: the @font-face is part of
 *  the DOM, Chromium blocks text paint on it (font-display: block), and the
 *  render is fully self-contained. Regenerate with the python block in git
 *  history if the font files change. OFL-licensed (Caveat, Patrick Hand). */
export const SKETCH_FONT_CSS = `@font-face { font-family: 'Caveat'; font-weight: 400; font-style: normal; font-display: block; src: url(data:font/woff2;base64,) format('woff2'); }\n@font-face { font-family: 'Caveat'; font-weight: 700; font-style: normal; font-display: block; src: url(data:font/woff2;base64,) format('woff2'); }\n@font-face { font-family: 'Patrick Hand'; font-weight: 400; font-style: normal; font-display: block; src: url(data:font/woff2;base64,) format('woff2'); }`;
